from pathlib import Path
p=Path('forge-of-heroes/index.html')
s=p.read_text()
old='{"kind":"passive_or_contextual","action":null,"cost":{"resource":"capacity","amount":2},"effects":[{"type":"table_runtime","scope":"canonical_runtime","sourceText":"Le barbare possède un tatouage magique qui améliore ses performances physiques ou mentales. Au choix : Taureau (+3 aux tests de FOR), ours (+3 aux tests de CON), panthère (+3 aux tests d’AGI), chouette (+3 aux tests de PER), loup (+3 aux tests de CHA), renard (+3 aux tests d’INT) ou serpent (+3 aux tests de VOL). De plus, lorsqu’il subit l’état étourdi, il est seulement ralenti."}],"sourceText":"Le barbare possède un tatouage magique qui améliore ses performances physiques ou mentales. Au choix : Taureau (+3 aux tests de FOR), ours (+3 aux tests de CON), panthère (+3 aux tests d’AGI), chouette (+3 aux tests de PER), loup (+3 aux tests de CHA), renard (+3 aux tests d’INT) ou serpent (+3 aux tests de VOL). De plus, lorsqu’il subit l’état étourdi, il est seulement ralenti."}'
new='{"kind":"passive_or_contextual","action":null,"cost":{"resource":"capacity","amount":2},"effects":[{"type":"table_runtime","scope":"canonical_runtime","sourceText":"Le barbare possède un tatouage magique qui améliore ses performances physiques ou mentales. Au choix : Taureau (+3 aux tests de FOR), ours (+3 aux tests de CON), panthère (+3 aux tests d’AGI), chouette (+3 aux tests de PER), loup (+3 aux tests de CHA), renard (+3 aux tests d’INT) ou serpent (+3 aux tests de VOL). De plus, lorsqu’il subit l’état étourdi, il est seulement ralenti."},{"type":"skill_bonus","choiceField":"tattooStat","value":3}],"sourceText":"Le barbare possède un tatouage magique qui améliore ses performances physiques ou mentales. Au choix : Taureau (+3 aux tests de FOR), ours (+3 aux tests de CON), panthère (+3 aux tests d’AGI), chouette (+3 aux tests de PER), loup (+3 aux tests de CHA), renard (+3 aux tests d’INT) ou serpent (+3 aux tests de VOL). De plus, lorsqu’il subit l’état étourdi, il est seulement ralenti.","choices":[{"id":"tattooStat","label":"Tatouage","type":"enum","values":["FOR","CON","AGI","PER","CHA","INT","VOL"],"valueLabels":{"FOR":"Taureau · FOR","CON":"Ours · CON","AGI":"Panthère · AGI","PER":"Chouette · PER","CHA":"Loup · CHA","INT":"Renard · INT","VOL":"Serpent · VOL"},"persist":true,"required":false}]}'
before="      else if(e.type==='skill_bonus')s.skillBonuses.push({sourceAbilityId:ability.id,tests:e.tests||[],value:semanticNumber(e.valueFormula||e.value,s,ctx),scope:e.scope||'self'});"
after="      else if(e.type==='skill_bonus'){\n        const selectedTest=e.choiceField?choices[e.choiceField]:null;\n        if(!e.choiceField||selectedTest)s.skillBonuses.push({sourceAbilityId:ability.id,tests:selectedTest?[selectedTest]:e.tests||[],value:semanticNumber(e.valueFormula||e.value,s,ctx),scope:e.scope||'self'});\n      }"
assert s.count(old)==s.count(before)==1
p.write_text(s.replace(old,new).replace(before,after))
